const products=[{id:'noir',number:'01',name:'Noir Absolu',family:'Woody / Amber',filters:['Woody','Amber'],price:185,tag:'Signature',desc:'Deep, mysterious and sophisticated.',notes:{top:'Bergamot',heart:'Rose',base:'Oud'}},{id:'velvet',number:'02',name:'Velvet Oud',family:'Oriental / Woody',filters:['Oriental','Woody'],price:210,tag:'Intense',desc:'Rich, warm and expressive.',notes:{top:'Saffron',heart:'Iris',base:'Oud'}},{id:'ambre',number:'03',name:'Ambre Noir',family:'Amber / Spicy',filters:['Amber'],price:195,tag:'New',desc:'Warm, elegant and unforgettable.',notes:{top:'Pink pepper',heart:'Amber',base:'Benzoin'}},{id:'eclat',number:'04',name:'Éclat Blanc',family:'Fresh / Floral',filters:['Fresh','Floral'],price:170,tag:'Luminous',desc:'Clean, luminous and refined.',notes:{top:'Bergamot',heart:'Rose',base:'Vanilla'}}].map(p=>({...p,sizes:{'50ml':p.price,'100ml':Math.round(p.price*1.55)}}));
const $=s=>document.querySelector(s),money=n=>`€${n}`;let filter='all';let cart=loadCart();
function loadCart(){try{let saved=JSON.parse(localStorage.getItem('sillage-cart')||'[]');return Array.isArray(saved)?saved.filter(i=>i&&getProduct(i.id)).map(i=>({...i,size:['50ml','100ml'].includes(i.size)?i.size:'50ml',qty:Number.isFinite(+i.qty)&&+i.qty>0?Math.floor(+i.qty):1})):[]}catch{return[]}}
function saveCart(){localStorage.setItem('sillage-cart',JSON.stringify(cart));renderCart()}function getProduct(id){return products.find(p=>p.id===id)}function cartKey(id,size){return `${id}:${size}`}
function productCard(p){return `<article class="product-card"><a href="#fragrance/${p.id}" class="product-visual" style="background-image:url('${encodeURI(ASSETS.products[p.id])}')"><span class="product-number">${p.number}</span><span class="product-tag">${p.tag}</span></a><div class="product-info"><div><h3>${p.name}</h3><p class="product-family">${p.family}</p><p class="product-price">${money(p.sizes['50ml'])} · 50ml</p></div><button class="quick-add" data-add="${p.id}">Add +</button></div></article>`}
