function openProduct(id,updateHash=true){let p=getProduct(id);if(updateHash)history.pushState({},'',`#fragrance/${id}`);$('#product-modal-content').innerHTML=`<div class="product-detail"><div class="detail-image" style="background-image:url('${encodeURI(ASSETS.products[p.id])}')"></div><div class="detail-copy"><span class="detail-family">${p.family} · ${p.tag}</span><h2>${p.name}</h2><p class="product-price" id="detail-price">${money(p.sizes['50ml'])} · 50ml</p><p class="detail-description">${p.desc} A refined composition designed to become part of your personal signature, lingering in the air and in the memory.</p><div class="detail-notes"><div><span>Top</span><strong>${p.notes.top}</strong></div><div><span>Heart</span><strong>${p.notes.heart}</strong></div><div><span>Base</span><strong>${p.notes.base}</strong></div></div><label class="size-label">Size<select id="detail-size"><option>50ml</option><option>100ml</option></select></label><button class="button button-light" id="detail-add">Add to bag <span>↗</span></button></div></div>`;$('#detail-size').onchange=e=>$('#detail-price').textContent=`${money(p.sizes[e.target.value])} · ${e.target.value}`;$('#detail-add').onclick=()=>{addToBag(p.id,$('#detail-size').value);closeModal('product-modal')};$('#product-modal').classList.add('open');$('#product-modal').setAttribute('aria-hidden','false')}
