function addToBag(id,size='50ml'){let found=cart.find(i=>cartKey(i.id,i.size)===cartKey(id,size));found?found.qty++:cart.push({id,size,qty:1});saveCart();openBag();toast(`${getProduct(id).name} added to bag`)}
function renderCart(){let count=cart.reduce((a,i)=>a+i.qty,0),total=cart.reduce((a,i)=>a+getProduct(i.id).sizes[i.size]*i.qty,0);$('#bag-count').textContent=count;$('#drawer-count').textContent=count;$('#bag-total').textContent=money(total);$('#bag-items').innerHTML=cart.length?cart.map(i=>{let p=getProduct(i.id);return `<div class="bag-item"><div class="bag-item-image" style="background-image:url('${encodeURI(ASSETS.products[p.id])}')"></div><div><h4>${p.name}</h4><p>${p.family} · ${i.size}</p><p>${money(p.sizes[i.size])}</p><div class="quantity"><button data-dec="${p.id}" data-size="${i.size}">−</button>${i.qty}<button data-inc="${p.id}" data-size="${i.size}">+</button></div></div><button class="remove" data-remove="${p.id}" data-size="${i.size}">×</button></div>`}).join(''):'<p class="empty-bag">Your bag is waiting.<br />Begin with a signature.</p>';document.querySelectorAll('[data-inc]').forEach(b=>b.onclick=()=>changeQty(b.dataset.inc,b.dataset.size,1));document.querySelectorAll('[data-dec]').forEach(b=>b.onclick=()=>changeQty(b.dataset.dec,b.dataset.size,-1));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(i=>cartKey(i.id,i.size)!==cartKey(b.dataset.remove,b.dataset.size));saveCart()})}
function changeQty(id,size,amount){let item=cart.find(i=>cartKey(i.id,i.size)===cartKey(id,size));if(!item)return;item.qty+=amount;if(item.qty<1)cart=cart.filter(i=>i!==item);saveCart()}function openBag(){$('#bag-drawer').classList.add('open');$('#drawer-backdrop').classList.add('open');$('#bag-drawer').setAttribute('aria-hidden','false')}function closeBag(){$('#bag-drawer').classList.remove('open');$('#drawer-backdrop').classList.remove('open');$('#bag-drawer').setAttribute('aria-hidden','true')}let toastTimer;function toast(m){clearTimeout(toastTimer);$('#toast').textContent=m;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
const quizQuestions=[['Which fragrance character attracts you most?',['Deep and mysterious','Warm and sensual','Fresh and energetic','Soft and elegant']],['Which ingredients interest you?',['Oud and woods','Amber and spices','Citrus and fresh accords','Florals and vanilla']],['When would you wear your fragrance?',['Evening occasions','Daily signature','Special occasions','Every moment']]],quizProfiles=[['noir','velvet','eclat','eclat'],['noir','ambre','eclat','eclat'],['velvet','noir','eclat','eclat']];let quizAnswers=[];
function renderQuiz(step=0){if(step<quizQuestions.length){let q=quizQuestions[step];$('#quiz-card').innerHTML=`<span class="quiz-progress">0${step+1} / 03</span><h3>${q[0]}</h3><div class="quiz-options">${q[1].map((o,i)=>`<button class="quiz-option" data-answer="${i}">${o}</button>`).join('')}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{quizAnswers[step]=+b.dataset.answer;renderQuiz(step+1)});return}let scores=Object.fromEntries(products.map(p=>[p.id,0]));quizAnswers.forEach((a,q)=>scores[quizProfiles[q][a]]++);let p=getProduct(Object.entries(scores).sort((a,b)=>b[1]-a[1])[0][0]);$('#quiz-card').innerHTML=`<span class="quiz-progress">Your signature</span><div class="quiz-result"><div class="result-visual" style="background-image:url('${encodeURI(ASSETS.products[p.id])}')"></div><div><h3>${p.name}</h3><p>${p.desc} Your answers point to a composition with ${p.family.toLowerCase()} character.</p><div class="quiz-actions"><button class="button button-light" data-add="${p.id}">View fragrance <span>↗</span></button><button class="text-link" id="restart">Restart</button></div></div></div>`;$('#quiz-card [data-add]').onclick=()=>openProduct(p.id);$('#restart').onclick=()=>{quizAnswers=[];renderQuiz()}}
document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelector('.filter.active').classList.remove('active');b.classList.add('active');filter=b.dataset.filter;renderProducts()});renderProducts();renderCart();renderQuiz();$('#bag-open').onclick=openBag;$('#bag-close').onclick=closeBag;$('#drawer-backdrop').onclick=closeBag;$('#checkout-button').onclick=()=>{closeBag();renderCheckoutSummary();$('#checkout-modal').classList.add('open');$('#checkout-modal').setAttribute('aria-hidden','false')};document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=()=>closeModal('checkout-modal'));document.querySelectorAll('.modal').forEach(m=>m.onclick=e=>{if(e.target===m)closeModal(m.id)});
function renderCheckoutSummary(){let total=cart.reduce((a,i)=>a+getProduct(i.id).sizes[i.size]*i.qty,0);$('#checkout-summary').innerHTML=cart.map(i=>`<div><span>${getProduct(i.id).name} · ${i.size} × ${i.qty}</span><strong>${money(getProduct(i.id).sizes[i.size]*i.qty)}</strong></div>`).join('')||'<div><span>Your bag is empty</span><strong>€0</strong></div>';$('#checkout-total').textContent=money(total)}$('#checkout-form').onsubmit=e=>{e.preventDefault();$('#checkout-message').textContent='Thank you. Your demonstration order is ready — no payment was processed.';e.target.querySelector('button').disabled=true};$('#newsletter-form').onsubmit=e=>{e.preventDefault();$('#form-message').textContent='Thank you. You are now part of the Sillage circle.';e.target.reset()};
window.addEventListener('hashchange',()=>{const match=location.hash.match(/^#fragrance\/(.+)$/);if(match&&getProduct(match[1]))openProduct(match[1],false)});const initialProduct=location.hash.match(/^#fragrance\/(.+)$/);if(initialProduct&&getProduct(initialProduct[1]))openProduct(initialProduct[1],false);
const video=$('#hero-video'),hero=$('.hero');
const HERO_STATES=Object.freeze({INTRO_PLAYING:'INTRO_PLAYING',INTRO_ENDING:'INTRO_ENDING',FINAL_IMAGE_REVEAL:'FINAL_IMAGE_REVEAL',FINAL_TEXT_REVEAL:'FINAL_TEXT_REVEAL',FINAL_HERO:'FINAL_HERO'});
const FINAL_IMAGE_URL='./public/images/brand/sillage-hero-after.webp';
let heroState=HERO_STATES.INTRO_PLAYING,heroTransitionStarted=false,finalImageReady=false;
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
window.__sillageHeroStates=[heroState];
hero.dataset.heroState=heroState;
function stateClass(state){return `hero--${state.toLowerCase().replaceAll('_','-')}`}
function setHeroState(nextState){
  if(heroState===nextState)return;
  const previousState=heroState;
  heroState=nextState;
  window.__sillageHeroStates.push(nextState);
  hero.className=`hero ${stateClass(nextState)}`;
  hero.dataset.heroState=nextState;
  const introOnly=nextState!==HERO_STATES.FINAL_TEXT_REVEAL&&nextState!==HERO_STATES.FINAL_HERO;
  document.body.classList.toggle('sillage-intro',introOnly);
  console.debug('[SILLAGE hero]',previousState,'→',nextState);
}
function preloadFinalImage(){
  return new Promise(resolve=>{
    const image=new Image();
    image.onload=()=>{const decoded=image.decode?image.decode().then(()=>true).catch(()=>false):Promise.resolve(true);decoded.then(ok=>{finalImageReady=ok;console.debug('[SILLAGE hero] final image decoded',FINAL_IMAGE_URL,ok);resolve(ok)})};
    image.onerror=()=>{finalImageReady=false;console.error('[SILLAGE hero] final image failed to load',FINAL_IMAGE_URL);resolve(false)};
    image.src=FINAL_IMAGE_URL;
  });
}
function startFinalTransition(){
  setHeroState(HERO_STATES.FINAL_IMAGE_REVEAL);
  setHeroState(HERO_STATES.FINAL_TEXT_REVEAL);
  setHeroState(HERO_STATES.FINAL_HERO);
  video.pause();
  video.style.opacity='0';
  video.style.pointerEvents='none';
  const hideVideo=()=>{
    video.style.visibility='hidden';
    console.debug('[SILLAGE hero] video hidden after crossfade');
  };
  if(reducedMotion||video.style.display==='none')hideVideo();
  else video.addEventListener('transitionend',hideVideo,{once:true});
}
function beginHeroTransition(reason='ended'){
  if(heroTransitionStarted||heroState!==HERO_STATES.INTRO_PLAYING){console.debug('[SILLAGE hero] transition ignored',reason);return}
  heroTransitionStarted=true;
  video.pause();
  console.debug('[SILLAGE hero] transition requested by',reason,'video paused');
  finalImageReadyPromise.then(()=>{
    setHeroState(HERO_STATES.INTRO_ENDING);
    if(!finalImageReady)hero.classList.add('hero--video-failed');
    startFinalTransition();
  });
}
video.src=ASSETS.video;video.loop=false;video.autoplay=true;video.muted=true;video.controls=false;
video.addEventListener('canplay',()=>{$('.hero-fallback').style.opacity='0';video.style.display='block';video.style.opacity='1';video.style.visibility='visible';console.debug('[SILLAGE hero] video canplay')});
video.addEventListener('ended',()=>beginHeroTransition('ended'),{once:true});
video.addEventListener('error',()=>{video.style.display='none';beginHeroTransition('video-error')},{once:true});
const finalImageReadyPromise=preloadFinalImage();
video.play().catch(error=>console.warn('[SILLAGE hero] video play rejected',error));

function getProductImage(productId){return ASSETS.products[productId]||''}
