function renderQuiz(step=0){if(step<quizQuestions.length){let q=quizQuestions[step];$('#quiz-card').innerHTML=`<span class="quiz-progress">0${step+1} / 03</span><h3>${q[0]}</h3><div class="quiz-options">${q[1].map((o,i)=>`<button class="quiz-option" data-answer="${i}">${o}</button>`).join('')}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{quizAnswers[step]=+b.dataset.answer;renderQuiz(step+1)});return}let scores=Object.fromEntries(products.map(p=>[p.id,0]));quizAnswers.forEach((a,q)=>scores[quizProfiles[q][a]]++);let p=getProduct(Object.entries(scores).sort((a,b)=>b[1]-a[1])[0][0]);$('#quiz-card').innerHTML=`<span class="quiz-progress">Your signature</span><div class="quiz-result"><div class="result-visual result-visual--${p.id}" data-image-path="${getProductImage(p.id)}" aria-hidden="true"></div><div><h3>${p.name}</h3><p>${p.desc} Your answers point to a composition with ${p.family.toLowerCase()} character.</p><div class="quiz-actions"><button class="button button-light" data-add="${p.id}">View fragrance <span>â†—</span></button><button class="text-link" id="restart">Restart</button></div></div></div>`;$('#quiz-card [data-add]').onclick=()=>openProduct(p.id);$('#restart').onclick=()=>{quizAnswers=[];renderQuiz()}}
