        <div class="product-gallery-thumbs" role="tablist" aria-label="${p.name} product images"><button type="button" class="product-gallery-thumb is-active" role="tab" aria-selected="true" data-image-path="${gallery.main}" data-image-label="${galleryImageLabel(p,0)}"><img src="${gallery.main}" alt="" loading="lazy" decoding="async"><span class="sr-only">Master image</span></button>${gallery.detail.map((path,index)=>`<button type="button" class="product-gallery-thumb" role="tab" aria-selected="false" hidden data-image-path="${path}" data-image-label="${galleryImageLabel(p,index+1)}"><img src="${path}" alt="" loading="lazy" decoding="async"><span class="sr-only">Detail image ${String(index+1).padStart(2,'0')}</span></button>`).join('')}</div>
        <p class="product-gallery-caption">${p.family} <span>—</span> SILLAGE / ${p.number}</p>
      </div>
